        // As we approach the end of the stream, discourage opening new bins
        score += progress * 50.0;
    }

    // 5. Critical Constraint: If this is the only fitting bin, accept it unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Start with the post_residual (Best Fit style).
    let mut score = post_residual as f64;

    // 1. Penalty for creating "slivers" (unusable space < 10, as items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead: If the next item fits into the post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global State: If we are nearing the end of the stream, prioritize compactness.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, it's a new bin candidate.
    // Only open a new bin if the current fit is extremely poor (large residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open if empty
        } else {
            // High penalty for opening a new bin unless the average residual is already high,
            // or the best existing fit is still quite wasteful.
            score = 45.0 + (mean_residual * 0.5);
        }
    }

    // 5. Fitting constraint: If this is the last bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Balance: Penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill levels across the active bin set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post_residual as f64;

    if is_new_bin {
        // Optimized new bin penalty: Increased threshold dependency on remaining items density.
        // We modulate the cost of a new bin by comparing current mean_residual to item_size.
        let density_factor = (mean_residual / 50.0).clamp(0.5, 1.5);
        let new_bin_base_penalty = 105.0 + (mean_residual * 0.42);
        score = new_bin_base_penalty + (fitting_bins_count as f64 * 22.0) * (1.1 - progress).max(0.12) * density_factor;
    } else {
        // Lookahead: Refined to identify "tight-fit" windows.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 38.0; 
                if post_residual == next_item_size { score -= 28.0; }
                // Dynamic threshold: Reward post-residuals that leave exactly space for the average expected item.
                if post_residual > 25 && post_residual < 50 { score -= 12.0; }
            } else if post_residual > 0 {
                score += 18.0;
            }
        }

        // Fragmentation Penalty:
        // Expanded and deepened the sliver penalty to prevent creating unfillable gaps.
        if post_residual > 0 && post_residual < 32 {
            score += (34.0 - post_residual as f64).powf(1.1) * (1.5 - progress).max(0.5);
        }

        // Global Load Balancing:
        // Penalize deviation from the mean_residual to encourage homogeneous bin states.
        if open_bins_count > 1 {
            let current_fill = bin_capacity - bin_residual;
            let deviation = (mean_residual - current_fill as f64).abs();
            score += (deviation / bin_capacity as f64) * 42.0 * (0.8 + progress);
        }
    }

    // Perfect fit reward: High-priority closure.
    if post_residual == 0 {
        score -= 68.0;
    } else if post_residual < 5 {
        score -= 22.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: Tightest fit (Best-Fit principle)
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        // New Bin Candidate logic: 
        // Penalize opening a new bin heavily early on, but allow it if existing 
        // bin utilization is poor (high mean_residual).
        let new_bin_base_penalty = 85.0 + (mean_residual * 0.95);
        score = new_bin_base_penalty + (fitting_bins_count as f64 * 22.0) * (1.2 - progress).max(0.3);
    } else {
        // Lookahead: Prioritize bins that maintain capacity for the next_item_size.
        // We use a non-linear lookahead to favor bins that leave "useful" space.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 42.0; 
            } else if post_residual > 0 {
                // Penalize bins that become "dead" (too small for next item)
                score += 12.0;
            }
        }

        // Adaptive Fragmentation Penalty:
        // Focus on eliminating slivers (1-15) which are statistically harder to fill.
        // Increased penalty weight for early-to-mid phase.
        if post_residual > 0 && post_residual <= 15 {
            let sliver_penalty = (16.0 - post_residual as f64) * 4.5;
            score += sliver_penalty * (1.0 + (open_bins_count as f64 * 0.08));
        }

        // Global Load Balancing:
        // Penalize bins that are too empty relative to the average, 
        // but only if the number of open bins is significant.
        if open_bins_count > 3 {
            let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
            score += (1.0 - fill_ratio) * 30.0 * (open_bins_count as f64 / 15.0).min(1.8);
        }

        // Reward perfect fits to encourage closing bins.
        if post_residual == 0 {
            score -= 65.0;
        }
    }

    // Heuristic safety valve: Discourage leaving large residuals in many open bins
    // to prevent a "long tail" of half-empty bins near the end of the stream.
    if open_bins_count > 5 {
        let residual_ratio = post_residual as f64 / bin_capacity as f64;
        if residual_ratio > 0.4 {
            score += 20.0 * residual_ratio;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
