        let end_game_multiplier = if progress > 0.92 { 4.5 } else if progress > 0.85 { 2.2 } else { 1.0 };
        let density_weight = (mean_residual / 32.0).clamp(0.4, 2.8);
        let new_bin_base_penalty = 178.0 + (mean_residual * 0.92);

        // Penalize opening a new bin if we have many options that could accommodate the current item
        // or if we are nearing the end of the stream, forcing higher density in existing bins.
        score = (new_bin_base_penalty + (fitting_bins_count as f64 * 54.0) * (1.7 - progress).max(0.3) * density_weight) * end_game_multiplier;
    } else {
        // Enhanced Lookahead: Prioritize bins that accommodate the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 94.0; 
                // Prioritize "tight" fits for upcoming items to minimize fragmentation.
                if post_residual < (next_item_size + 8) { score -= 38.0; }
            } else {
