        // Adaptive Fragmentation Penalty: Aggressive penalty for small slivers (1-42) that are hard to fill.
        // We dampen this penalty as the stream ends to allow for final bin closure.
        if post_residual > 0 && post_residual < 43 {
            score += (44.0 - post_residual as f64).powf(1.85) * (2.6 - progress).max(0.5);
        }

