        if open_bins_count > 1 {
            let target_residual = mean_residual * (0.9 - (progress * 0.25));
            let deviation = (target_residual - post_residual as f64).abs();
            score += (deviation / bin_capacity as f64) * 115.0 * (1.0 + progress * 0.5);
        }
    }

    // Perfect fit reward: Non-linear scaling favoring exact matches.
    if post_residual == 0 {
        score -= 165.0;
    } else if post_residual < 4 {
